#include "bridge.h"
#include <QDir>
#include <QFile>
#include <QFileInfo>
#include <QStandardPaths>
#include <QTextStream>
PelicanBridge::PelicanBridge(QObject *p):QObject(p){QDir().mkpath(scriptsRoot());}
QString PelicanBridge::scriptsRoot() const{return QStandardPaths::writableLocation(QStandardPaths::DocumentsLocation)+"/PelicanExecutor/Scripts";}
QString PelicanBridge::safeScriptPath(const QString &name) const{QString n=name.trimmed();if(n.isEmpty()||n.contains('/')||n.contains('\\')||n=="."||n=="..")return {};QString b=QFileInfo(n).completeBaseName();if(b.isEmpty())return {};return QDir::cleanPath(scriptsRoot()+"/"+b+".luau");}
QVariantList PelicanBridge::listScripts() const{QVariantList out;QDir d(scriptsRoot());for(const QFileInfo &f:d.entryInfoList({"*.luau","*.lua"},QDir::Files,QDir::Name))out.push_back(f.fileName());return out;}
QString PelicanBridge::readScript(const QString &n) const{QString p=safeScriptPath(n);if(p.isEmpty())return {};QFile f(p);if(!f.open(QIODevice::ReadOnly|QIODevice::Text))return {};QTextStream s(&f);return s.readAll();}
bool PelicanBridge::saveScript(const QString &n,const QString &c){QString p=safeScriptPath(n);if(p.isEmpty())return false;QFile f(p);if(!f.open(QIODevice::WriteOnly|QIODevice::Text|QIODevice::Truncate))return false;QTextStream s(&f);s<<c;return f.error()==QFile::NoError;}
bool PelicanBridge::deleteScript(const QString &n){QString p=safeScriptPath(n);return !p.isEmpty()&&QFileInfo(p).isFile()&&QFile::remove(p);}
QString PelicanBridge::appVersion() const{return QStringLiteral("0.2.0");}
QVariantMap PelicanBridge::attachDemo(const QString &n) const{QString nick=n.trimmed();QVariantMap r;r["ok"]=!nick.isEmpty();r["nickname"]=nick;r["status"]=nick.isEmpty()?"Enter a demo nickname":"Demo profile only — not connected to Roblox";return r;}
QString PelicanBridge::uiHtml(){return QString::fromUtf8(R"HTML(<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;height:100vh;background:#101319;color:#e6eaf0;font:14px 'Segoe UI',sans-serif;display:flex;flex-direction:column}header,footer{display:flex;align-items:center;gap:12px;padding:12px 18px;background:#171b23}header .brand{font-size:17px;font-weight:800;color:#b8d4ff}.spacer{flex:1}input,button,textarea{font:inherit;color:inherit;background:#171c25;border:1px solid #364153;border-radius:7px;padding:8px}button{cursor:pointer}main{display:flex;flex:1;min-height:0}aside{width:230px;padding:12px;background:#151922;display:flex;flex-direction:column;gap:8px}#scripts{flex:1;overflow:auto}.script{display:block;width:100%;text-align:left;margin:3px 0}section{display:flex;flex:1;flex-direction:column}.toolbar{display:flex;gap:7px;padding:10px}#editor{flex:1;resize:none;border:0;background:#101319;padding:16px;font:14px Consolas,monospace}footer{color:#aab5c5}#status{flex:1}</style></head><body><header><span class="brand">PELICAN</span><span>Script Workbench</span><span class="spacer"></span><input id="nick" placeholder="Demo nickname"><button onclick="attach()">Attach (demo)</button></header><main><aside><button onclick="fresh()">＋ New script</button><b>Saved scripts</b><div id="scripts"></div><button onclick="refresh()">Refresh</button></aside><section><div class="toolbar"><input id="name" value="Untitled"><button onclick="save()">Save</button><button onclick="removeScript()">Delete</button></div><textarea id="editor" spellcheck="false" placeholder="-- Luau source"></textarea></section></main><footer><span id="status">Ready</span><span id="player">Player: —</span><span id="version">Pelican</span></footer><script src="qrc:///qtwebchannel/qwebchannel.js"></script><script>let current='Untitled';function status(t){document.getElementById('status').textContent=t}new QWebChannel(qt.webChannelTransport,c=>{window.api=c.objects.pelican;api.appVersion(v=>document.getElementById('version').textContent='Pelican '+v);refresh()});function fresh(){current='Untitled';document.getElementById('name').value=current;document.getElementById('editor').value='';status('New script')}function refresh(){if(!window.api)return;api.listScripts(a=>{let b=document.getElementById('scripts');b.innerHTML='';a.forEach(n=>{let x=document.createElement('button');x.className='script';x.textContent=n;x.onclick=()=>api.readScript(n,t=>{current=n.replace(/\\.(lua|luau)$/i,'');document.getElementById('name').value=current;document.getElementById('editor').value=t;status('Opened '+n)});b.appendChild(x)})})}function save(){let n=document.getElementById('name').value.trim();api.saveScript(n,document.getElementById('editor').value,ok=>{status(ok?'Saved '+n+'.luau':'Save failed');if(ok){current=n;refresh()}})}function removeScript(){if(!confirm('Delete '+current+'.luau?'))return;api.deleteScript(current,ok=>{status(ok?'Deleted '+current:'Could not delete');refresh()})}function attach(){api.attachDemo(document.getElementById('nick').value,r=>{status(r.status);document.getElementById('player').textContent='Player: '+(r.nickname||'—')})}</script></body></html>)HTML");}
